• System.Text.Encoding.GetEncoding(System.Int32)?displayProperty=fullName

• System.Text.Encoding.GetEncoding(System.String)?displayProperty=fullName

• System.Text.Encoding.GetEncoding(System.Int32,System.Text.EncoderFallback,System.Text.DecoderFallback)?displayProperty=fullName

• System.Text.Encoding.GetEncoding(System.String,System.Text.EncoderFallback,System.Text.DecoderFallback)?displayProperty=fullName

