• System.IO.Compression.DeflateStream.Read*?displayProperty=fullName

• System.IO.Compression.DeflateStream.ReadAsync*?displayProperty=fullName

• System.IO.Compression.DeflateStream.BeginRead(System.Byte[],System.Int32,System.Int32,System.AsyncCallback,System.Object)?displayProperty=fullName

• System.IO.Compression.GZipStream.Read*?displayProperty=fullName

• System.IO.Compression.GZipStream.ReadAsync*?displayProperty=fullName

• System.IO.Compression.GZipStream.BeginRead(System.Byte[],System.Int32,System.Int32,System.AsyncCallback,System.Object)?displayProperty=fullName

• System.Security.Cryptography.CryptoStream.Read*?displayProperty=fullName

