Order and sort strings

Typically, ordered strings that are to be displayed in the user interface should be sorted based on culture. For the most part, such string comparisons are handled implicitly by .NET when you call a method that sorts strings, such as System.Array.Sort*?displayProperty=nameWithType or [System.Collections.Generic.List1.Sort*?displayProperty=nameWithType](xref:System.Collections.Generic.List1.Sort*?displayProperty=nameWithType). By default, strings are sorted by using the sorting conventions of the current culture. The following example illustrates the difference when an array of strings is sorted by using the conventions of the English (United States) culture and the Swedish (Sweden) culture.

    using System;
    using System.Globalization;
    using System.Threading;

    public class Example18
    {
        public static void Main18()
        {
            string[] values = { "able", "ångström", "apple", "Æble",
                              "Windows", "Visual Studio" };
            // Change thread to en-US.
            Thread.CurrentThread.CurrentCulture = CultureInfo.CreateSpecificCulture("en-US");
            // Sort the array and copy it to a new array to preserve the order.
            Array.Sort(values);
            string[] enValues = (String[])values.Clone();

            // Change culture to Swedish (Sweden).
            Thread.CurrentThread.CurrentCulture = CultureInfo.CreateSpecificCulture("sv-SE");
            Array.Sort(values);
            string[] svValues = (String[])values.Clone();

            // Compare the sorted arrays.
            Console.WriteLine("{0,-8} {1,-15} {2,-15}\n", "Position", "en-US", "sv-SE");
            for (int ctr = 0; ctr <= values.GetUpperBound(0); ctr++)
                Console.WriteLine("{0,-8} {1,-15} {2,-15}", ctr, enValues[ctr], svValues[ctr]);
        }
    }

    // The example displays the following output:
    //       Position en-US           sv-SE
    //
    //       0        able            able
    //       1        Æble            Æble
    //       2        ångström        apple
    //       3        apple           Windows
    //       4        Visual Studio   Visual Studio
    //       5        Windows         ångström

    Imports System.Globalization
    Imports System.Threading

    Module Example18
        Public Sub Main18()
            Dim values() As String = {"able", "ångström", "apple",
                                       "Æble", "Windows", "Visual Studio"}
