    '       487.0313743534644
    '       674.12000879371533
    '       498.72077885024288
    '       42.3034229512808
    '       970.57311049223563
    '       531.33717716268131
    '       587.82905693530529
    '       562.25210175023039
    '       600.7711019370571
    '       299.46113717717174
    '
    '       Current Culture: French (France)
    '       ERROR: Unable to parse '487.0313743534644'
    '       ERROR: Unable to parse '674.12000879371533'
    '       ERROR: Unable to parse '498.72077885024288'
    '       ERROR: Unable to parse '42.3034229512808'
    '       ERROR: Unable to parse '970.57311049223563'
    '       ERROR: Unable to parse '531.33717716268131'
    '       ERROR: Unable to parse '587.82905693530529'
    '       ERROR: Unable to parse '562.25210175023039'
    '       ERROR: Unable to parse '600.7711019370571'
    '       ERROR: Unable to parse '299.46113717717174'

To avoid this problem, you can use one of these techniques:

• Save and parse the string representation of the number by using a custom format string that is the same regardless of the user's culture.

• Save the number as a string by using the formatting conventions of the invariant culture, which is returned by the System.Globalization.CultureInfo.InvariantCulture?displayProperty=nameWithType property.

Serializing currency values is a special case. Because a currency value depends on the unit of currency in which it's expressed, it makes little sense to treat it as an independent numeric value. However, if you save a currency value as a formatted string that includes a currency symbol, it cannot be deserialized on a system whose default culture uses a different currency symbol, as the following example shows.

    using System;
    using System.Globalization;
    using System.IO;
    using System.Threading;

    public class Example1
    {
       public static void Main1()
       {
          // Display the currency value.
          Thread.CurrentThread.CurrentCulture = CultureInfo.CreateSpecificCulture("en-US");
          Decimal value = 16039.47m;
          Console.WriteLine($"Current Culture: {CultureInfo.CurrentCulture.DisplayName}");
          Console.WriteLine($"Currency Value: {value:C2}");

          // Persist the currency value as a string.
          StreamWriter sw = new StreamWriter("currency.dat");
          sw.Write(value.ToString("C2"));
          sw.Close();

          // Read the persisted data using the current culture.
          StreamReader sr = new StreamReader("currency.dat");
          string currencyData = sr.ReadToEnd();
          sr.Close();

          // Restore and display the data using the conventions of the current culture.
          Decimal restoredValue;
          if (Decimal.TryParse(currencyData, out restoredValue))
             Console.WriteLine(restoredValue.ToString("C2"));
          else
             Console.WriteLine($"ERROR: Unable to parse '{currencyData}'");
          Console.WriteLine();

          // Restore and display the data using the conventions of the en-GB culture.
          Thread.CurrentThread.CurrentCulture = CultureInfo.CreateSpecificCulture("en-GB");
          Console.WriteLine($"Current Culture: {Thread.CurrentThread.CurrentCulture.DisplayName}");
          if (Decimal.TryParse(currencyData, NumberStyles.Currency, null, out restoredValue))
             Console.WriteLine(restoredValue.ToString("C2"));
          else
             Console.WriteLine($"ERROR: Unable to parse '{currencyData}'");
          Console.WriteLine();
       }
    }
    // The example displays output like the following:
    //       Current Culture: English (United States)
    //       Currency Value: $16,039.47
    //       ERROR: Unable to parse '$16,039.47'
    //
    //       Current Culture: English (United Kingdom)
    //       ERROR: Unable to parse '$16,039.47'

    Imports System.Globalization
    Imports System.IO
    Imports System.Threading

    Module Example1
        Public Sub Main1()
            ' Display the currency value.
            Thread.CurrentThread.CurrentCulture = CultureInfo.CreateSpecificCulture("en-US")
            Dim value As Decimal = 16039.47D
            Console.WriteLine("Current Culture: {0}", CultureInfo.CurrentCulture.DisplayName)
            Console.WriteLine("Currency Value: {0:C2}", value)

            ' Persist the currency value as a string.
            Dim sw As New StreamWriter("currency.dat")
            sw.Write(value.ToString("C2"))
            sw.Close()

            ' Read the persisted data using the current culture.
            Dim sr As New StreamReader("currency.dat")
            Dim currencyData As String = sr.ReadToEnd()
            sr.Close()

            ' Restore and display the data using the conventions of the current culture.
            Dim restoredValue As Decimal
            If Decimal.TryParse(currencyData, restoredValue) Then
                Console.WriteLine(restoredValue.ToString("C2"))
            Else
                Console.WriteLine("ERROR: Unable to parse '{0}'", currencyData)
            End If
            Console.WriteLine()

            ' Restore and display the data using the conventions of the en-GB culture.
            Thread.CurrentThread.CurrentCulture = CultureInfo.CreateSpecificCulture("en-GB")
            Console.WriteLine("Current Culture: {0}",
                              Thread.CurrentThread.CurrentCulture.DisplayName)
            If Decimal.TryParse(currencyData, NumberStyles.Currency, Nothing, restoredValue) Then
                Console.WriteLine(restoredValue.ToString("C2"))
            Else
                Console.WriteLine("ERROR: Unable to parse '{0}'", currencyData)
            End If
            Console.WriteLine()
        End Sub
    End Module
    ' The example displays output like the following:
    '       Current Culture: English (United States)
    '       Currency Value: $16,039.47
    '       ERROR: Unable to parse '$16,039.47'
    '
    '       Current Culture: English (United Kingdom)
    '       ERROR: Unable to parse '$16,039.47'

Instead, you should serialize the numeric value along with some cultural information, such as the name of the culture, so that the value and its currency symbol can be deserialized independently of the current culture. The following example does that by defining a CurrencyValue structure with two members: the System.Decimal value and the name of the culture to which the value belongs.

    using System;
    using System.Globalization;
    using System.Text.Json;
    using System.Threading;

    public class Example2
    {
        public static void Main2()
        {
            // Display the currency value.
            Thread.CurrentThread.CurrentCulture = CultureInfo.CreateSpecificCulture("en-US");
            Decimal value = 16039.47m;
            Console.WriteLine($"Current Culture: {CultureInfo.CurrentCulture.DisplayName}");
            Console.WriteLine($"Currency Value: {value:C2}");

            // Serialize the currency data.
            CurrencyValue data = new()
            {
                Amount = value,
                CultureName = CultureInfo.CurrentCulture.Name
            };
            string serialized = JsonSerializer.Serialize(data);
            Console.WriteLine();

            // Change the current culture.
            CultureInfo.CurrentCulture = CultureInfo.CreateSpecificCulture("en-GB");
            Console.WriteLine($"Current Culture: {CultureInfo.CurrentCulture.DisplayName}");

            // Deserialize the data.
            CurrencyValue restoredData = JsonSerializer.Deserialize<CurrencyValue>(serialized);

            // Display the round-tripped value.
            CultureInfo culture = CultureInfo.CreateSpecificCulture(restoredData.CultureName);
            Console.WriteLine($"Currency Value: {restoredData.Amount.ToString("C2", culture)}");
        }
    }

    internal struct CurrencyValue
    {
        public decimal Amount { get; set; }
        public string CultureName { get; set; }
    }

    // The example displays the following output:
    //       Current Culture: English (United States)
    //       Currency Value: $16,039.47
    //
    //       Current Culture: English (United Kingdom)
    //       Currency Value: $16,039.47

    Imports System.Globalization
    Imports System.Text.Json
    Imports System.Threading

    Friend Structure CurrencyValue
        Public Property Amount As Decimal
        Public Property CultureName As String
    End Structure

    Module Example2
        Public Sub Main2()
            ' Display the currency value.
            Thread.CurrentThread.CurrentCulture = CultureInfo.CreateSpecificCulture("en-US")
            Dim value As Decimal = 16039.47D
            Console.WriteLine("Current Culture: {0}", CultureInfo.CurrentCulture.DisplayName)
            Console.WriteLine("Currency Value: {0:C2}", value)

            ' Serialize the currency data.
            Dim data As New CurrencyValue With {
                .Amount = value,
                .CultureName = CultureInfo.CurrentCulture.Name
            }

            Dim serialized As String = JsonSerializer.Serialize(data)
            Console.WriteLine()

            ' Change the current culture.
            CultureInfo.CurrentCulture = CultureInfo.CreateSpecificCulture("en-GB")
            Console.WriteLine("Current Culture: {0}", CultureInfo.CurrentCulture.DisplayName)

            ' Deserialize the data.
            Dim restoredData As CurrencyValue = JsonSerializer.Deserialize(Of CurrencyValue)(serialized)

            ' Display the round-tripped value.
            Dim culture As CultureInfo = CultureInfo.CreateSpecificCulture(restoredData.CultureName)
            Console.WriteLine("Currency Value: {0}", restoredData.Amount.ToString("C2", culture))
        End Sub
    End Module

    ' The example displays the following output:
    '       Current Culture: English (United States)
    '       Currency Value: $16,039.47
    '
    '       Current Culture: English (United Kingdom)
    '       Currency Value: $16,039.47

Work with culture-specific settings

In .NET, the System.Globalization.CultureInfo class represents a particular culture or region. Some of its properties return objects that provide specific information about some aspect of a culture:

• The System.Globalization.CultureInfo.CompareInfo?displayProperty=nameWithType property returns a System.Globalization.CompareInfo object that contains information about how the culture compares and orders strings.

• The System.Globalization.CultureInfo.DateTimeFormat?displayProperty=nameWithType property returns a System.Globalization.DateTimeFormatInfo object that provides culture-specific information used in formatting date and time data.

• The System.Globalization.CultureInfo.NumberFormat?displayProperty=nameWithType property returns a System.Globalization.NumberFormatInfo object that provides culture-specific information used in formatting numeric data.

• The System.Globalization.CultureInfo.TextInfo?displayProperty=nameWithType property returns a System.Globalization.TextInfo object that provides information about the culture's writing system.

In general, do not make any assumptions about the values of specific System.Globalization.CultureInfo properties and their related objects. Instead, you should view culture-specific data as subject to change, for these reasons:

• Individual property values are subject to change and revision over time, as data is corrected, better data becomes available, or culture-specific conventions change.

• Individual property values may vary across versions of .NET or operating system versions.

• .NET supports replacement cultures. This makes it possible to define a new custom culture that either supplements existing standard cultures or completely replaces an existing standard culture.

• On Windows systems, the user can customize culture-specific settings by using the Region and Language app in Control Panel. When you instantiate a System.Globalization.CultureInfo object, you can determine whether it reflects these user customizations by calling the System.Globalization.CultureInfo.%23ctor%28System.String%2CSystem.Boolean%29 constructor. Typically, for end-user apps, you should respect user preferences so that the user is presented with data in a format that they expect.

