    });

    var app = builder.Build();
    app.MapControllers();
    var serverTask = app.RunAsync();

    using var httpClient = new HttpClient();
    var baseUrl = "http://localhost:5000";
    httpClient.BaseAddress = new Uri(baseUrl);

