When the current UI culture is Spanish (Spain), note that the example displays English language resources, because Spanish language resources are unavailable, and English is the example's default culture.

Retrieve object data examples

You can use the System.Resources.ResourceManager.GetObject* and System.Resources.ResourceManager.GetStream* methods to retrieve object data. This includes primitive data types, serializable objects, and objects that are stored in binary format (such as images).

The following example uses the System.Resources.ResourceManager.GetStream%28System.String%29 method to retrieve a bitmap that is used in an app's opening splash window. The following source code in a file named CreateResources.cs (for C#) or CreateResources.vb (for Visual Basic) generates a .resx file that contains the serialized image. In this case, the image is loaded from a file named SplashScreen.jpg; you can modify the file name to substitute your own image.

    using System;
    using System.Drawing;
    using System.Drawing.Imaging;
    using System.IO;
    using System.Resources;

    public class Example
    {
       public static void Main()
       {
          Bitmap bmp = new Bitmap(@".\SplashScreen.jpg");
          MemoryStream imageStream = new MemoryStream();
          bmp.Save(imageStream, ImageFormat.Jpeg);

          ResXResourceWriter writer = new ResXResourceWriter("AppResources.resx");
          writer.AddResource("SplashScreen", imageStream);
          writer.Generate();
          writer.Close();
       }
    }

    Imports System.Drawing
    Imports System.Drawing.Imaging
    Imports System.IO
    Imports System.Resources

    Module Example
        Public Sub Main()
            Dim bmp As New Bitmap(".\SplashScreen.jpg")
            Dim imageStream As New MemoryStream()
            bmp.Save(imageStream, ImageFormat.Jpeg)

            Dim writer As New ResXResourceWriter("AppResources.resx")
            writer.AddResource("SplashScreen", imageStream)
            writer.Generate()
            writer.Close()
        End Sub
    End Module

The following code retrieves the resource and displays the image in a System.Windows.Forms.PictureBox control.

    using System;
    using System.Drawing;
    using System.IO;
    using System.Resources;
    using System.Windows.Forms;

    public class Example
    {
       public static void Main()
       {
          ResourceManager rm = new ResourceManager("AppResources", typeof(Example).Assembly);
          Bitmap screen = (Bitmap) Image.FromStream(rm.GetStream("SplashScreen"));

          Form frm = new Form();
          frm.Size = new Size(300, 300);

          PictureBox pic = new PictureBox();
          pic.Bounds = frm.RestoreBounds;
          pic.BorderStyle = BorderStyle.Fixed3D;
          pic.Image = screen;
          pic.SizeMode = PictureBoxSizeMode.StretchImage;

          frm.Controls.Add(pic);
          pic.Anchor = AnchorStyles.Top | AnchorStyles.Bottom |
                       AnchorStyles.Left | AnchorStyles.Right;

          frm.ShowDialog();
       }
    }

    Imports System.Drawing
    Imports System.IO
    Imports System.Resources
    Imports System.Windows.Forms

    Module Example
        Public Sub Main()
            Dim rm As New ResourceManager("AppResources", GetType(Example).Assembly)
            Dim screen As Bitmap = CType(Image.FromStream(rm.GetStream("SplashScreen")), Bitmap)

            Dim frm As New Form()
            frm.Size = new Size(300, 300)

            Dim pic As New PictureBox()
            pic.Bounds = frm.RestoreBounds
            pic.BorderStyle = BorderStyle.Fixed3D
            pic.Image = screen
            pic.SizeMode = PictureBoxSizeMode.StretchImage

            frm.Controls.Add(pic)
            pic.Anchor = AnchorStyles.Top Or AnchorStyles.Bottom Or
                         AnchorStyles.Left Or AnchorStyles.Right

            frm.ShowDialog()
        End Sub
    End Module

