 System.Int64?displayProperty=nameWithType   long   L

 System.UInt64?displayProperty=nameWithType   ulong   UL

 System.Double?displayProperty=nameWithType   double   D

 System.Single?displayProperty=nameWithType   float   F

 System.Decimal?displayProperty=nameWithType   decimal   M

    int num = 10;
    ConstantExpression expr = Expression.Constant(num);
    /*
        10
    */

    double num = 10;
    ConstantExpression expr = Expression.Constant(num);
    /*
        10D
    */

