    {
        // <GenericMethods>
        static void Print<T>(T value) =>
            Console.WriteLine($"Value: {value}");

        Print(42);        // Compiler infers T as int
        Print("hello");   // Compiler infers T as string
        Print(3.14);      // Compiler infers T as double
        // </GenericMethods>
    }

