How to combine and compare string collections

This example shows how to merge files that contain lines of text and then sort the results. Specifically, it shows how to perform a concatenation, a union, and an intersection on the two sets of text lines. It uses the same two text files shows in the preceding example. The code shows examples of the System.Linq.Enumerable.Concat*?displayProperty=nameWithType, System.Linq.Enumerable.Union*?displayProperty=nameWithType, and System.Linq.Enumerable.Except*?displayProperty=nameWithType.

    //Put text files in your solution folder
    string[] fileA = File.ReadAllLines("names1.txt");
    string[] fileB = File.ReadAllLines("names2.txt");

    //Simple concatenation and sort. Duplicates are preserved.
    var concatQuery = fileA.Concat(fileB).OrderBy(s => s);

    // Pass the query variable to another function for execution.
    OutputQueryResults(concatQuery, "Simple concatenate and sort. Duplicates are preserved:");

    // Concatenate and remove duplicate names based on
    // default string comparer.
    var uniqueNamesQuery = fileA.Union(fileB).OrderBy(s => s);
    OutputQueryResults(uniqueNamesQuery, "Union removes duplicate names:");

    // Find the names that occur in both files (based on
    // default string comparer).
    var commonNamesQuery = fileA.Intersect(fileB);
    OutputQueryResults(commonNamesQuery, "Merge based on intersect:");

    // Find the matching fields in each list. Merge the two
    // results by using Concat, and then
    // sort using the default string comparer.
    string nameMatch = "Garcia";

    var tempQuery1 = from name in fileA
                     let n = name.Split(',')
                     where n[0] == nameMatch
                     select name;

    var tempQuery2 = from name2 in fileB
                     let n2 = name2.Split(',')
                     where n2[0] == nameMatch
                     select name2;

    var nameMatchQuery = tempQuery1.Concat(tempQuery2).OrderBy(s => s);
    OutputQueryResults(nameMatchQuery, $"""Concat based on partial name match "{nameMatch}":""");

