    class MyClass
    {
        enum Color
        {
            Red = Blue,   // CS0110
            Blue,
        }

        public const int a = b + 1;   // CS0110
        public const int b = a + 1;
    }

To resolve this error, break the circular reference by modifying or removing the definition.

