    class Test
        {
            int num;
            public void TestMethod()
            {
                this.num = 5; // Error fixed.
                int num = 6;
            }
            public static int Main()
            {
                return 1;
            }
        }

Correct the error by giving the local variable a different name from the class field

    class Test
        {
            int num;
            public void TestMethod()
            {
                num = 5; // Error fixed.
                int num2 = 6;
            }
            public static int Main()
            {
                return 1;
            }
        }

