The following example shows how to convert a byte array to a hexadecimal string by using the System.BitConverter?displayProperty=nameWithType class.

    byte[] vals = [0x01, 0xAA, 0xB1, 0xDC, 0x10, 0xDD];

    string str = BitConverter.ToString(vals);
    Console.WriteLine(str);

    str = BitConverter.ToString(vals).Replace("-", "");
    Console.WriteLine(str);

