            Actions[] action = {Actions.Unknown,Actions.Unknown,
                             Actions.Unknown,Actions.Unknown,
                             Actions.Unknown,Actions.Unknown};
            bool[] disposition = new bool[5];
            int i = 0;

            foreach (TypeOfFeedback t in Enum.GetValues(typeof(TypeOfFeedback)))
            {
                // The call to the library.
                disposition[i] = BadRefAndOut.ReplyInformation(
                   t, out reply[i], ref action[i]);
                Console.WriteLine($"Reply: {reply[i]} Action: {action[i]}  return? {disposition[i]} ");
                i++;
            }
        }

        static void UseTheSimplifiedClass()
        {
            ReplyData[] answer = new ReplyData[5];
            int i = 0;
            foreach (TypeOfFeedback t in Enum.GetValues(typeof(TypeOfFeedback)))
            {
                // The call to the library.
                answer[i] = RedesignedRefAndOut.ReplyInformation(t);
                Console.WriteLine(answer[i++]);
            }
        }

        public static void UseClasses()
        {
            UseTheComplicatedClass();

            // Print a blank line in output.
            Console.WriteLine("");

            UseTheSimplifiedClass();
        }
    }

Example 3

The following example library illustrates how ref parameters for reference types are used and shows a better way to implement this functionality.

    public class ReferenceTypesAndParameters
    {
        // The following syntax will not work. You cannot make a
        // reference type that is passed by value point to a new
        // instance. This needs the ref keyword.

        public static void BadPassTheObject(string argument)
        {
            argument += " ABCDE";
        }

        // The following syntax works, but is considered bad design.
        // It reassigns the argument to point to a new instance of string.
        // Violates rule DoNotPassTypesByReference.

        public static void PassTheReference(ref string argument)
        {
            argument += " ABCDE";
        }

        // The following syntax works and is a better design.
        // It returns the altered argument as a new instance of string.

        public static string BetterThanPassTheReference(string argument)
        {
            return argument + " ABCDE";
        }
    }

Example 4

The following application calls each method in the library to demonstrate the behavior.

    public class Test
    {
        public static void MainTest()
        {
            string s1 = "12345";
            string s2 = "12345";
            string s3 = "12345";

            Console.WriteLine("Changing pointer - passed by value:");
            Console.WriteLine(s1);
            ReferenceTypesAndParameters.BadPassTheObject(s1);
            Console.WriteLine(s1);

            Console.WriteLine("Changing pointer - passed by reference:");
            Console.WriteLine(s2);
            ReferenceTypesAndParameters.PassTheReference(ref s2);
            Console.WriteLine(s2);

            Console.WriteLine("Passing by return value:");
            s3 = ReferenceTypesAndParameters.BetterThanPassTheReference(s3);
            Console.WriteLine(s3);
        }
    }

This example produces the following output:

    Changing pointer - passed by value:
    12345
    12345
    Changing pointer - passed by reference:
    12345
    12345 ABCDE
    Passing by return value:
    12345 ABCDE

Try pattern methods

Methods that implement the Try<Something> pattern, such as System.Int32.TryParse*?displayProperty=fullName, do not raise this violation. The following example shows a structure (value type) that implements the System.Int32.TryParse*?displayProperty=fullName method.

    public struct Point
    {
        public Point(int axisX, int axisY)
        {
            X = axisX;
            Y = axisY;
        }

        public int X { get; }

        public int Y { get; }

        public override int GetHashCode()
        {
            return X ^ Y;
        }

        public override bool Equals(object? obj)
        {
            if (!(obj is Point))
                return false;

            return Equals((Point)obj);
        }

        public bool Equals(Point other)
        {
            if (X != other.X)
                return false;

            return Y == other.Y;
        }

        public static bool operator ==(Point point1, Point point2)
        {
            return point1.Equals(point2);
        }

        public static bool operator !=(Point point1, Point point2)
        {
            return !point1.Equals(point2);
        }

        // Does not violate this rule
        public static bool TryParse(string value, out Point result)
        {
            // TryParse Implementation
            result = new Point(0, 0);
            return false;
        }
    }

