The following code fixes the previous violation by overriding System.ValueType.Equals*?displayProperty=fullName and implementing the equality operators (== and !=):

    public struct Point : IEquatable<Point>
    {
        public Point(int x, int y)
        {
            X = x;
            Y = y;
        }

        public int X { get; }

        public int Y { get; }

        public override int GetHashCode()
        {
            return X ^ Y;
        }

        public override bool Equals(object? obj)
        {
            if (!(obj is Point))
                return false;

            return Equals((Point)obj);
