Rename the numeric placeholder.

For usage examples, see the Microsoft.Extensions.Logging.LoggerExtensions.LogInformation*?displayProperty=nameWithType method.

Example

    public class UserService
    {
        private readonly ILogger<UserService> _logger;

        public UserService(ILogger<UserService> logger)
        {
            _logger = logger;
        }

        public void Add(string firstName, string lastName)
        {
            // This code violates the rule.
            _logger.LogInformation("Adding user with first name {0} and last name {1}", firstName, lastName);

            // This code satisfies the rule.
