Violation

    using System;

    [Serializable()]
    unsafe class TestClassA
    {
        private int* pointer;
    }

Solution 1

    using System;

    [Serializable()]
    unsafe class TestClassA
    {
        private int i;
    }

Solution 2

    using System;

    [Serializable()]
    unsafe class TestClassA
    {
        private static int* pointer;
    }

